import { extract, test } from "../../deps/front-matter.js";
import { read } from "../utils/read.js";
/** Load a text file. Detect and parse the front matter */
export default async function text(path) {
    const content = await read(path, false);
    if (test(content)) {
        let { attrs, body } = extract(content);
        attrs ??= {};
        attrs.content = body;
        return attrs;
    }
    return { content };
}
